/* zo: shop overlay root + Shop tab entry (outside the scoped handoff styles) */
#cshop{position:fixed;inset:0;z-index:84;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;padding:env(safe-area-inset-top,0px) env(safe-area-inset-right,0px) env(safe-area-inset-bottom,0px) env(safe-area-inset-left,0px);text-align:left;touch-action:pan-y}
#cshop[hidden]{display:none!important}
#cshop.csmodalonly{background:transparent!important}#cshop.csmodalonly #cs-app{display:none}
#cshop .shell{min-height:100%}
body.csopen .dov{z-index:95}
.csentry{display:flex;align-items:center;gap:12px;width:100%;margin:0 0 10px;padding:10px 14px;border:3px solid #17121f;border-radius:14px;background:linear-gradient(135deg,#3b1d4a,#6b2f6f 55%,#a5672a);color:#fff3d8;text-align:left;cursor:pointer;box-shadow:0 4px 0 #17121f;font:inherit}
.csentry:active{transform:translateY(2px);box-shadow:0 2px 0 #17121f}
.csentry .csg{width:64px;height:72px;object-fit:contain;flex:none;filter:drop-shadow(0 3px 2px #0008)}
.csentry .cst{flex:1;min-width:0}.csentry b{display:block;font:400 22px/1.05 'Luckiest Guy',Georgia,serif;letter-spacing:.5px;color:#ffd35a;text-shadow:0 2px 0 #17121f}
.csentry small{display:block;font-size:12px;opacity:.92;margin-top:3px}.csentry em{display:block;font-style:normal;font-weight:800;font-size:12px;color:#a6f3c8;margin-top:4px}
.csentry .csgo{flex:none;background:#ffcf4e;color:#2a1626;border:2px solid #17121f;border-radius:10px;padding:8px 12px;font:400 16px/1 'Luckiest Guy',Georgia,serif}
/* zo: short landscape phones (the game is landscape-only), keep popups readable without hunting for the buttons */
@media (max-height:520px) and (orientation:landscape){
 #cshop .overlay{padding:6px}
 #cshop .dialog{max-height:calc(100dvh - 12px);padding:8px 12px;border-width:11px}
 #cshop .dialog-head{margin-bottom:6px;padding-bottom:4px}
 #cshop .dialog h2,#cshop .detail .copy h2{font-size:26px;margin:4px 0 6px}
 #cshop .dialog p{margin:5px 0;font-size:12px;line-height:1.4}
 #cshop .summary-art,#cshop .receipt .summary-art,#cshop .dialog.narrow .receipt .summary-art{height:70px}
 #cshop .welcome-die{width:54px;height:54px;margin:-26px auto 4px}
 #cshop .reminder-die{width:76px;height:76px;margin:4px auto}
 #cshop .dialog footer{padding-top:8px;margin-top:8px}
 #cshop .dialog footer button{font-size:15px;padding:8px 10px;min-height:44px}
 #cshop .detail{grid-template-columns:minmax(0,38%) 1fr;gap:12px}
 #cshop .stage{max-width:none;border-width:7px}
 #cshop .stage canvas{max-height:calc(100dvh - 150px)}
 #cshop .detail .copy label{margin-top:6px}
 #cshop .detail .copy select{min-height:40px;padding:6px}
}
/* zv: phones felt oversized (Kenneth, wide Android). Scale the whole shop page, so the category bar fits in one row. */
@media (max-height:520px) and (orientation:landscape){#cshop #cs-app{zoom:.64}}
@media (min-height:521px) and (max-height:760px) and (max-width:1100px){#cshop #cs-app{zoom:.8}}
@media (max-height:520px) and (orientation:landscape){#cshop #cs-modal-root{zoom:.8}#cshop #cs-modal-root .dialog{max-height:calc((100dvh - 12px) / .8)}#cshop #cs-modal-root .stage canvas{max-height:calc((100dvh - 150px) / .8)}}
